import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './styles/base.scss'
// Theme of the "Luciérnagas" brand (design/brand, generated by design/brand/tools/build.py).
// Order matters: tokens.css defines --nm-* and theme-base.css assigns them to the base stylesheet's variables.
import '../../../design/brand/tokens.css'
import '../../../design/brand/theme-base.css'
import './styles/brand.css'
// The UI's own styles (nm-* classes). They go last: they only use the variables above and, at equal
// specificity, must win over the base stylesheet's rules.
import './styles/app.css'
import App from './App.tsx'
import { prefs } from './prefs.ts'
import { watchInputModality } from './modality.ts'
import { watchStillness } from './stillness.ts'

// The saved theme was already applied by `public/tema.js` before painting; repeated here in case that script never
// loaded (the store is the authority from now on). With "system" there is no attribute and `tokens.css` follows the
// machine on its own, also if it changes while the app is open: no need to listen for it.
prefs.apply()
// With the window unfocused or hidden, endless animations stop (without a GPU, every frame costs CPU).
watchStillness()
// The focus ring only shows when the keyboard is in use (modality.ts and the "keyboard-only focus" part of app.css).
watchInputModality()

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
